/// The item table of category number `cat` (the C number; 6 is `LC_ALL`, none) of "C" or "C.UTF-8".
pub(crate) fn items(utf8: bool, cat: i32) -> Tab {
    match (utf8, cat) {
        (false, 0) => Tab::Packed(&C_0),
        (true, 0) => Tab::Packed(&C_UTF8_0),
        (false, 1) => Tab::Packed(&C_1),
        (true, 1) => Tab::Packed(&C_UTF8_1),
        (false, 2) => Tab::Packed(&C_2),
        (true, 2) => Tab::Packed(&C_UTF8_2),
        (false, 3) => Tab::Packed(&C_3),
        (true, 3) => Tab::Packed(&C_UTF8_3),
        (false, 4) => Tab::Packed(&C_4),
        (true, 4) => Tab::Packed(&C_UTF8_4),
        (false, 5) => Tab::Packed(&C_5),
        (true, 5) => Tab::Packed(&C_UTF8_5),
        (false, 7) => Tab::Packed(&C_7),
        (true, 7) => Tab::Packed(&C_UTF8_7),
        (false, 8) => Tab::Packed(&C_8),
        (true, 8) => Tab::Packed(&C_UTF8_8),
        (false, 9) => Tab::Packed(&C_9),
        (true, 9) => Tab::Packed(&C_UTF8_9),
        (false, 10) => Tab::Packed(&C_10),
        (true, 10) => Tab::Packed(&C_UTF8_10),
        (false, 11) => Tab::Packed(&C_11),
        (true, 11) => Tab::Packed(&C_UTF8_11),
        (false, 12) => Tab::Packed(&C_12),
        (true, 12) => Tab::Packed(&C_UTF8_12),
        _ => Tab::Items(&[]),
    }
}
